51	type ComponentKind = { id: string; label: string; kind: string; icon: React.ComponentType<{ className?: string }>; promptHint: string };
52	const COMPONENT_KINDS: ComponentKind[] = [
53	  { id: "card",      label: "Card Deck",    kind: "card",     icon: Layers,   promptHint: "a hand-illustrated card with title bar, central art frame, and rule text area" },
54	  { id: "board",     label: "Game Board",   kind: "board",    icon: Square,   promptHint: "a top-down game board with hex or grid regions, paths, and iconography" },
55	  { id: "token",     label: "Token Set",    kind: "token",    icon: Circle,   promptHint: "a set of small circular player tokens with distinct icons and colors" },
