73	// ── Gamma prompt builders ─────────────────────────────────────────────────────
74	
75	function buildDeckPrompt(
76	  deck: Entity,
77	  cards: Entity[],
78	  projectName: string,
79	  narrative: string,
80	): string {
81	  const cardList = cards.length
82	    ? cards.map((c, i) =>
83	        `${i + 1}. **${c.name}**${c.subtype ? ` (${c.subtype})` : ""}${c.description ? ` — ${c.description}` : ""}${c.lore ? `\n   Lore: "${c.lore}"` : ""}`
84	      ).join("\n")
85	    : "No cards defined yet.";
86	
87	  return `Please generate a Gamma PDF presentation for my board game deck.
88	
89	**Game:** ${projectName}
90	**Narrative:** ${narrative || "(none)"}
91	
92	**Deck:** ${deck.name}${deck.subtype ? ` (${deck.subtype})` : ""}
93	**Description:** ${deck.description || "(none)"}${deck.lore ? `\n**Flavor/Lore:** ${deck.lore}` : ""}${deck.designNotes ? `\n**Designer Notes:** ${deck.designNotes}` : ""}
94	
95	**Cards in this deck (${cards.length}):**
96	${cardList}
97	
98	Create a polished PDF presentation (exportAs: pdf) with:
99	- Cover slide: deck name and themed board-game illustration
100	- Deck overview: purpose, strategy, card count
101	- One slide per card: name, subtype, art concept, rules text, flavor quote
102	- Quick-reference summary table
103	
104	Use the game narrative and art style to keep illustrations consistent. Share the PDF link when done.`;
105	}
106	
107	function buildEntityPrompt(
108	  entity: Entity,
109	  projectName: string,
110	  narrative: string,
111	): string {
112	  const meta = getMeta(entity.type);
113	  return `Please generate a Gamma document for a game component.
114	
115	**Game:** ${projectName}
116	**Narrative:** ${narrative || "(none)"}
