72	function parseStats(raw: string | null | undefined): { key: string; val: string }[] {
73	  if (!raw) return [];
74	  return raw
75	    .split(/[/\n]/)
76	    .map((s) => s.trim())
77	    .filter(Boolean)
78	    .map((s) => {
79	      const m = s.match(/^([^:=0-9]+?)\s*[:=]?\s*(\S+)\s*$/);
80	      if (m) return { key: m[1].trim(), val: m[2] };
81	      const n = s.match(/^([\D]+?)\s*(\d[\d.]*)\s*$/);
82	      if (n) return { key: n[1].trim(), val: n[2] };
83	      return { key: s, val: "" };
84	    });
85	}
